    public void CalculateShipping_Exactly250_ChargesShipping()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(250m, 2.0, false);
        Assert.AreEqual(6.00m, cost);
    }

    [TestMethod]
    public void CalculateShipping_JustAbove250_FreeShipping()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(0m, calc.CalculateShipping(250.01m, 2.0, false));
    }

    // Kills: removal of heavy item fee or > 10 → >= 10
    [TestMethod]
    public void CalculateShipping_Exactly10kg_NoHeavyFee()
    {
        var calc = new DiscountCalculator();
        // base = 5 + 10*0.50 = 10.00, no heavy fee
        Assert.AreEqual(10.00m, calc.CalculateShipping(50m, 10.0, false));
    }

    [TestMethod]
    public void CalculateShipping_Over10kg_IncludesHeavyFee()
    {
        var calc = new DiscountCalculator();
        // base = 5 + 10.1*0.50 = 10.05, + 15 heavy fee = 25.05
        Assert.AreEqual(25.05m, calc.CalculateShipping(50m, 10.1, false));
    }

    // Kills: removal of express surcharge or wrong multiplier
    [TestMethod]
    public void CalculateShipping_Express_Adds50PercentSurcharge()
    {
        var calc = new DiscountCalculator();
        // base = 5 + 2*0.50 = 6.00, express = 6 * 1.50 = 9.00
        Assert.AreEqual(9.00m, calc.CalculateShipping(50m, 2.0, true));
    }

    [TestMethod]
    public void CalculateShipping_HeavyAndExpress_BothApplied()
    {
        var calc = new DiscountCalculator();
        // base = 5 + 11*0.50 = 10.50, + 15 heavy = 25.50, * 1.50 express = 38.25
        Assert.AreEqual(38.25m, calc.CalculateShipping(50m, 11.0, true));
    }

    // -- ApplyCoupon gap tests --
    // Kills: SAVE20/FLAT5 branch removal
    [TestMethod]
    public void ApplyCoupon_Save20_Applies20Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(80m, calc.ApplyCoupon(100m, "SAVE20"));
    }

    [TestMethod]
    public void ApplyCoupon_Flat5_SubtractsFive()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(95m, calc.ApplyCoupon(100m, "FLAT5"));
    }

    // Kills: unknown coupon returning nonzero discount
    [TestMethod]
    public void ApplyCoupon_UnknownCode_NoDiscount()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(100m, calc.ApplyCoupon(100m, "BOGUS"));
    }

    // Kills: floor < 1.00 → removal or wrong floor value
    [TestMethod]
    public void ApplyCoupon_DiscountWouldGoBelowMinimum_ClampsTo1()
    {
        var calc = new DiscountCalculator();
        // FLAT50 on a 10.00 total → 10 - 50 = -40 → clamped to 1.00
        Assert.AreEqual(1.00m, calc.ApplyCoupon(10m, "FLAT50"));
    }

    [TestMethod]
    public void ApplyCoupon_DiscountLeavesExactlyMinimum_Returns1()
    {
        var calc = new DiscountCalculator();
        // FLAT5 on 6.00 → 6 - 5 = 1.00 (exactly the floor)
        Assert.AreEqual(1.00m, calc.ApplyCoupon(6m, "FLAT5"));
    }

    [TestMethod]
    public void ApplyCoupon_DiscountLeavesJustAboveMinimum_ReturnsActual()
    {
        var calc = new DiscountCalculator();
        // FLAT5 on 7.00 → 7 - 5 = 2.00 (above floor, no clamping)
        Assert.AreEqual(2.00m, calc.ApplyCoupon(7m, "FLAT5"));
    }

    // Kills: case-sensitivity mutation (removing ToUpperInvariant)
    [TestMethod]
    public void ApplyCoupon_LowercaseCode_StillApplies()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(90m, calc.ApplyCoupon(100m, "save10"));
    }
}

